contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 amount) public {
        require(spender != address(0), "spender zero");
        require(amount > 0, "amount zero");
        require(c.balanceOf(address(this)) >= amount, "insufficient balance");
        bool ok = c.approve(spender, amount);
        require(ok, "approve failed");
        uint256 beforeAllowance = c.allowance(address(this), spender);
        require(beforeAllowance == amount, "allowance not set");
        require(c.balanceOf(spender) + amount >= amount, "overflow");
        uint256 beforeSpenderBal = c.balanceOf(spender);
        bool ok2 = c.transferFrom(address(this), spender, amount);
        require(ok2, "transferFrom failed");
        uint256 afterAllowance = c.allowance(address(this), spender);
        uint256 afterSpenderBal = c.balanceOf(spender);
        assert(afterAllowance == beforeAllowance - amount && afterSpenderBal == beforeSpenderBal + amount);
    }
    receive() external payable {}
}

